const DEFAULT_USER = { email: '', password: '' };
const num = value => Number.parseFloat(value || 0) || 0;
const autoProductSku = p => {
  const code = String(p.category || 'PRD').replace(/[^A-Za-z]/g, '').slice(0, 3).toUpperCase() || 'PRD';
  const slug = String(p.name || 'PRODUCT').replace(/[^A-Za-z0-9]/g, '').slice(0, 4).toUpperCase() || 'PROD';
  return `${code}-${slug}-${String(Math.floor(Math.random() * 9000) + 1000)}`;
};
const currency = value => {
  const n = Number(value || 0);
  if (!Number.isFinite(n)) return 'Ksh0';
  return `Ksh${n.toLocaleString('en-KE', { maximumFractionDigits: 0 })}`;
};
const compactCurrency = value => {
  const n = Number(value || 0);
  if (!Number.isFinite(n)) return 'Ksh0';
  const abs = Math.abs(n);
  const sign = n < 0 ? '-' : '';
  if (abs >= 1_000_000_000) return `Ksh${sign}${(abs / 1_000_000_000).toFixed(2)}B`;
  if (abs >= 1_000_000) return `Ksh${sign}${(abs / 1_000_000).toFixed(2)}M`;
  if (abs >= 10_000) return `Ksh${sign}${(abs / 1_000).toFixed(1)}K`;
  return `Ksh${sign}${Math.round(abs).toLocaleString('en-KE')}`;
};
const heroValue = value => {
  if (typeof value === 'number' && Number.isFinite(value)) {
    // Counts stay plain; money uses compact
    if (Math.abs(value) >= 1000 && String(Math.round(value)).length > 5) return compactCurrency(value);
    if (Math.abs(value) >= 10000) return compactCurrency(value);
    return Math.round(value).toLocaleString('en-KE');
  }
  const s = String(value ?? '0');
  if (/^Ksh/i.test(s)) return s;
  const n = Number(String(s).replace(/[^0-9.-]/g, ''));
  if (Number.isFinite(n) && Math.abs(n) >= 10000) return compactCurrency(n);
  return s;
};
const shortCurrency = value => {
  const n = Number(value || 0);
  if (Math.abs(n) >= 1000000) return `Ksh${(n / 1000000).toFixed(n >= 10000000 ? 0 : 1)}M`;
  if (Math.abs(n) >= 1000) return `Ksh${Math.round(n / 1000)}K`;
  return `Ksh${Math.round(n).toLocaleString()}`;
};
const dateValue = row => String(row?.date || row?.createdAt || row?.created_at || row?.updatedAt || new Date().toISOString()).slice(0, 10);
function sortByDateDesc(rows, key = 'createdAt') {
  return [...(rows || [])].sort((a, b) => {
    const da = new Date(a?.[key] || a?.date || a?.created_at || a?.updatedAt || 0);
    const db = new Date(b?.[key] || b?.date || b?.created_at || b?.updatedAt || 0);
    return db - da;
  });
}
