function QuotesWorkspace({ user, quotes = [], onDone, customers = [], canGenerateInvoice = true }) {
  const [busy, setBusy] = useState('');
  const [statusMsg, setStatusMsg] = useState('');
  const [quoteModalOpen, setQuoteModalOpen] = useState(false);
  async function act(quote, action) {
    setBusy(`${quote.id}-${action}`);
    setStatusMsg('');
    try {
      if (action === 'Send Quote') {
        const res = await rpc('sendQuotation', [user, quote.id]);
        setStatusMsg(res.emailSent ? `${quote.quoteNo} sent by email to customer` : `${quote.quoteNo} marked as Sent (no customer email)`);
      } else if (action === 'Convert To Order') {
        const res = await rpc('convertQuotationToSale', [user, quote.id]);
        setStatusMsg(`${quote.quoteNo} converted to Sale ${res.saleNo}`);
      } else if (action === 'Generate Invoice') {
        const res = await rpc('generateInvoiceFromQuote', [user, quote.id]);
        setStatusMsg(res.success ? `Invoice ${res.invoice.invNo} generated${res.emailSent ? ' and emailed' : ''}` : 'Could not generate invoice');
      } else if (action === 'Download PDF') {
        const res = await rpc('generateQuotePdf', [user, quote.id]);
        if (res.content) downloadBase64File(res);
        setStatusMsg(res.content ? 'Quote PDF downloaded' : 'PDF generation failed');
      } else       if (action === 'Email Quote') {
        const res = await rpc('sendQuoteEmail', [user, quote.id]);
        setStatusMsg(res.sent ? `Quote emailed to ${res.to}` : 'Email failed');
      } else if (action === 'Print') {
        const res = await rpc('generateQuotePdf', [user, quote.id]);
        if (res.content) openBase64File(res, true);
      } else if (action === 'WhatsApp') {
        const phone = prompt('Enter WhatsApp number (e.g. +254712345678):');
        if (!phone) { setBusy(''); return; }
        const msg = encodeURIComponent(`Quotation ${quote.quoteNo}\nCustomer: ${quote.customerName}\nTotal: KES ${quote.total?.toLocaleString()}\nStatus: ${quote.status}\n\nView at: https://erpftc.vercel.app/#/sales`);
        window.open(`https://wa.me/${phone.replace(/[^0-9+]/g, '')}?text=${msg}`, '_blank');
        setStatusMsg('WhatsApp opened');
      }
      onDone?.();
    } catch (e) {
      setStatusMsg(e.message || 'Action failed');
    } finally {
      setBusy('');
    }
  }
   return (
     <div>
      {quoteModalOpen && <QuotationModal user={user} customers={customers || quotes} onClose={() => setQuoteModalOpen(false)} onSaved={() => { setQuoteModalOpen(false); onDone?.(); }} />}
      <Panel title="Quotation Workflow">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
          <span style={{ fontWeight: 600, color: '#344054' }}>All Quotations</span>
          <button className="primary-action" onClick={() => setQuoteModalOpen(true)}><Plus size={14} /> New Quote</button>
        </div>
        {statusMsg && <div className="quote-status-msg">{statusMsg}</div>}
        <div className="quote-workflow">
          {quotes.map(quote => {
            const menuActions = [
              quote.status === 'Draft' && { label: 'Send quote', icon: <Send size={15} />, disabled: busy === `${quote.id}-Send Quote`, onClick: () => act(quote, 'Send Quote') },
              quote.status === 'Sent' && { label: 'Convert to order', icon: <ArrowRight size={15} />, disabled: busy === `${quote.id}-Convert To Order`, onClick: () => act(quote, 'Convert To Order') },
              canGenerateInvoice && (quote.status === 'Converted' || quote.status === 'Sent') && { label: 'Generate invoice', icon: <ReceiptText size={15} />, disabled: busy === `${quote.id}-Generate Invoice`, onClick: () => act(quote, 'Generate Invoice') },
              { label: 'Download PDF', icon: <Download size={15} />, disabled: busy === `${quote.id}-Download PDF`, onClick: () => act(quote, 'Download PDF') },
              { label: 'Email quote', icon: <Mail size={15} />, disabled: busy === `${quote.id}-Email Quote`, onClick: () => act(quote, 'Email Quote') },
              { label: 'Print', icon: <Printer size={15} />, disabled: busy === `${quote.id}-Print`, onClick: () => act(quote, 'Print') },
              { label: 'WhatsApp', icon: <Phone size={15} />, disabled: busy === `${quote.id}-WhatsApp`, onClick: () => act(quote, 'WhatsApp') },
              { label: 'Copy details', icon: <FileText size={15} />, onClick: () => copyText(rowSummary(quote)) }
            ].filter(Boolean);
            return (
              <article key={quote.id}>
                <div>
                  <strong>{quote.quoteNo}</strong>
                  <span>{quote.customerName} · {quote.status} · {quote.conversionProbability}% probability</span>
                </div>
                <b>{currency(quote.total)}</b>
                <div className="quote-actions" onClick={e => e.stopPropagation()}>
                  {quote.status === 'Draft' && <button onClick={() => act(quote, 'Send Quote')} disabled={busy === `${quote.id}-Send Quote`}><Send size={14} /> Send</button>}
                  {quote.status === 'Sent' && <button onClick={() => act(quote, 'Convert To Order')} disabled={busy === `${quote.id}-Convert To Order`}><ArrowRight size={14} /> Convert</button>}
                  {canGenerateInvoice && quote.status === 'Converted' && <button onClick={() => act(quote, 'Generate Invoice')} disabled={busy === `${quote.id}-Generate Invoice`}><FileText size={14} /> Invoice</button>}
                  {quote.status === 'Invoiced' && <span className="badge badge-success">Complete</span>}
                  <ActionMenu actions={menuActions} summary={quote.quoteNo} />
                </div>
              </article>
            );
          })}
        </div>
      </Panel>
    </div>
  );
}

function standardRowActions(row = {}, extras = []) {
  const title = row.name || row.productName || row.saleNo || row.invNo || row.invoiceNo || row.orderNo || row.deliveryNo || row.applicantName || 'Record';
  const text = rowSummary(row);
  return [
    ...extras.filter(Boolean),
    { label: 'Copy details', icon: <FileText size={15} />, onClick: () => copyText(text) },
    { label: 'Print summary', icon: <Printer size={15} />, onClick: () => printText(title, text) },
    { label: 'Export row CSV', icon: <Download size={15} />, onClick: () => downloadRowsFile(String(title).replace(/\s+/g, '-').toLowerCase(), [row], 'CSV') }
  ];
}

function ActionMenu({ actions = [], align = 'right', summary, quickActions = 0 }) {
  const [open, setOpen] = useState(false);
  const [focusedIndex, setFocusedIndex] = useState(-1);
  const [coords, setCoords] = useState({ top: 0, left: 0, right: 0 });
  const filtered = actions.filter(Boolean);
  const usable = filtered.length
    ? filtered
    : [
        summary && { label: 'Copy', icon: <FileText size={15} />, onClick: () => copyText(String(summary)) },
        summary && { label: 'Print', icon: <Printer size={15} />, onClick: () => printText('Record', String(summary)) }
      ].filter(Boolean);
  const ref = useRef(null);
  const triggerRef = useRef(null);
  const panelRef = useRef(null);
  const quick = quickActions > 0 ? usable.slice(0, quickActions) : [];
  const rest = quickActions > 0 ? usable.slice(quickActions) : usable;

  const placePanel = useCallback(() => {
    const el = triggerRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    const panelW = 200;
    const leftPreferred = align === 'left' ? r.left : r.right - panelW;
    const left = Math.max(8, Math.min(leftPreferred, window.innerWidth - panelW - 8));
    const spaceBelow = window.innerHeight - r.bottom;
    const openUp = spaceBelow < 220 && r.top > spaceBelow;
    setCoords({
      top: openUp ? undefined : r.bottom + 6,
      bottom: openUp ? window.innerHeight - r.top + 6 : undefined,
      left
    });
  }, [align]);

  useEffect(() => {
    if (!open) return;
    setFocusedIndex(-1);
    placePanel();
    const close = e => {
      if (ref.current && !ref.current.contains(e.target) && panelRef.current && !panelRef.current.contains(e.target)) setOpen(false);
    };
    const onKey = e => {
      if (e.key === 'Escape') { setOpen(false); return; }
      if (e.key === 'ArrowDown') { e.preventDefault(); setFocusedIndex(i => Math.min(i + 1, rest.length - 1)); }
      if (e.key === 'ArrowUp') { e.preventDefault(); setFocusedIndex(i => Math.max(i - 1, 0)); }
      if (e.key === 'Enter' && focusedIndex >= 0 && focusedIndex < rest.length) {
        e.preventDefault();
        const act = rest[focusedIndex];
        if (!act?.disabled) { setOpen(false); act?.onClick?.(); }
      }
    };
    const onScroll = () => placePanel();
    document.addEventListener('pointerdown', close);
    document.addEventListener('keydown', onKey);
    window.addEventListener('resize', placePanel);
    window.addEventListener('scroll', onScroll, true);
    return () => {
      document.removeEventListener('pointerdown', close);
      document.removeEventListener('keydown', onKey);
      window.removeEventListener('resize', placePanel);
      window.removeEventListener('scroll', onScroll, true);
    };
  }, [open, focusedIndex, rest, placePanel]);

  if (!usable.length) return null;
  const menuPanel = open && typeof document !== 'undefined' ? createPortal(
    <div
      ref={panelRef}
      className={`row-action-panel fixed-panel ${align}`}
      role="menu"
      onPointerDown={e => e.stopPropagation()}
      onMouseDown={e => e.stopPropagation()}
      onClick={e => e.stopPropagation()}
      style={{
        position: 'fixed',
        top: coords.top,
        bottom: coords.bottom,
        left: coords.left,
        right: 'auto',
        zIndex: 12000
      }}
    >
      {summary && <div className="row-action-summary">{summary}</div>}
      {rest.map((action, idx) => (
        <button
          key={action.label}
          type="button"
          role="menuitem"
          disabled={action.disabled}
          className={focusedIndex === idx ? 'focused' : ''}
          onPointerDown={event => event.stopPropagation()}
          onMouseDown={event => event.stopPropagation()}
          onClick={async event => {
            event.preventDefault();
            event.stopPropagation();
            if (action.disabled) return;
            setOpen(false);
            await action.onClick?.();
          }}
        >
          {action.icon}
          <span>{action.label}</span>
          {action.shortcut && <em className="action-shortcut">{action.shortcut}</em>}
        </button>
      ))}
    </div>,
    document.body
  ) : null;
  return (
    <div className={`row-action-menu ${open ? 'is-open' : ''}`} ref={ref} onPointerDown={e => e.stopPropagation()} onMouseDown={e => e.stopPropagation()} onClick={e => e.stopPropagation()}>
      {quick.map(action => (
        <button key={action.label} type="button" className="row-quick-action" disabled={action.disabled} onPointerDown={e => e.stopPropagation()} onMouseDown={e => e.stopPropagation()} onClick={async e => { e.stopPropagation(); await action.onClick?.(); }} title={action.label}>
          {action.icon}
        </button>
      ))}
      {rest.length > 0 && (
        <>
          <button
            type="button"
            ref={triggerRef}
            className="row-action-trigger"
            aria-haspopup="menu"
            aria-expanded={open}
            onPointerDown={e => {
              e.stopPropagation();
            }}
            onMouseDown={e => e.stopPropagation()}
            onClick={e => {
              e.preventDefault();
              e.stopPropagation();
              setOpen(v => !v);
            }}
            aria-label="Row actions"
            title={summary || `${rest.length} actions`}
          >
            <MoreVertical size={16} />
          </button>
          {menuPanel}
        </>
      )}
    </div>
  );
}

function SalesOrdersWorkspace({ user, orders, deliveries, onDone, canGenerateInvoice = true }) {
  const [busy, setBusy] = useState('');
  async function setDeliveryStatus(order, status) {
    const deliveryId = order.deliveryId || deliveries.find(row => row.saleId === order.id || row.saleNo === order.saleNo)?.id;
    if (!deliveryId) return;
    setBusy(`${deliveryId}-${status}`);
    try {
      await rpc('updateSalesDeliveryStatus', [user, deliveryId, status]);
      onDone?.();
    } finally {
      setBusy('');
    }
  }
  async function toggleDelivery(order, checked) {
    const deliveryId = order.deliveryId || deliveries.find(row => row.saleId === order.id || row.saleNo === order.saleNo)?.id;
    if (!deliveryId) return;
    setBusy(deliveryId);
    try {
      await rpc('confirmSalesDelivery', [user, deliveryId, checked]);
      onDone?.();
    } finally {
      setBusy('');
    }
  }
  async function generateInvoice(order) {
    setBusy(`${order.id}-invoice`);
    try {
      await rpc('generateInvoiceFromSale', [user, order.id]);
      onDone?.();
    } finally {
      setBusy('');
    }
  }
  async function deleteOrder(order) {
    if (!window.confirm(`Delete sales order ${order.saleNo || order.id}? It will stay in Restore Center.`)) return;
    setBusy(`${order.id}-delete`);
    try {
      await rpc('deleteRecord', [user, 'sales', order.id || order.saleNo]);
      onDone?.();
    } catch (error) {
      alert(error.message || 'Could not delete sales order');
    } finally {
      setBusy('');
    }
  }
  const [detailOrder, setDetailOrder] = useState(null);
  function actionsFor(order) {
    const summary = rowSummary(order);
    const deliveryId = order.deliveryId || deliveries.find(row => row.saleId === order.id || row.saleNo === order.saleNo)?.id;
    const liveStatus = order.liveStatus || '';
    return [
      { label: 'View details', icon: <FileText size={15} />, onClick: () => setDetailOrder(order) },
      { label: 'Mark Picked', icon: <ClipboardCheck size={15} />, disabled: !deliveryId || liveStatus === 'Delivered', onClick: () => setDeliveryStatus(order, 'Picked') },
      { label: 'Mark Dispatched', icon: <Truck size={15} />, disabled: !deliveryId || liveStatus === 'Delivered', onClick: () => setDeliveryStatus(order, 'Dispatched') },
      { label: liveStatus === 'Delivered' ? 'Unconfirm Delivery' : 'Confirm Delivered', icon: <CheckCircle2 size={15} />, disabled: !deliveryId, onClick: () => toggleDelivery(order, liveStatus !== 'Delivered') },
      canGenerateInvoice && { label: 'Generate Invoice', icon: <ReceiptText size={15} />, onClick: () => generateInvoice(order) },
      { label: 'Copy Details', icon: <FileText size={15} />, onClick: () => copyText(summary) },
      { label: 'Print Summary', icon: <Printer size={15} />, onClick: () => printText(order.saleNo || 'Sales Order', summary) },
      { label: 'Delete order', icon: <X size={15} />, disabled: busy === `${order.id}-delete`, onClick: () => deleteOrder(order) }
    ];
  }
  return (
    <div className="dashboard-grid">
      <Panel className="span-12" title="Orders + Delivery Confirmation" action={`${(orders || []).length} orders`}>
        <div className="table-wrap">
          <table>
            <thead><tr><th>Sale No</th><th>Customer</th><th>Products</th><th>Destination</th><th>Total</th><th>Paid</th><th>Balance</th><th>Delivery</th><th>Confirmed</th><th>Actions</th></tr></thead>
            <tbody>
              {(orders || []).map(order => (
                <tr key={order.id} onClick={() => setDetailOrder(order)} style={{ cursor: 'pointer' }}>
                  <td><strong>{order.saleNo}</strong></td>
                  <td>{order.customerName}</td>
                  <td><strong>{order.productCount != null ? `${order.productCount} product${order.productCount === 1 ? '' : 's'}` : '—'}</strong><small>{order.productsSummary || ''}</small></td>
                  <td>{order.destination || '—'}</td>
                  <td>{currency(order.total)}</td>
                  <td>{currency(order.paid)}</td>
                  <td>{currency(order.balance || (num(order.total) - num(order.paid)))}</td>
                  <td>{formatCell(order.liveStatus, 'status')}</td>
                  <td onClick={e => e.stopPropagation()}>
                    <label className="check-cell">
                      <input type="checkbox" checked={Boolean(order.deliveredConfirmed || order.liveStatus === 'Delivered')} disabled={busy === order.deliveryId || !order.deliveryId} onChange={e => toggleDelivery(order, e.target.checked)} />
                      <span>{order.deliveryNo || 'No delivery'}</span>
                    </label>
                  </td>
                  <td onClick={e => e.stopPropagation()}><ActionMenu actions={actionsFor(order)} summary={order.saleNo} /></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Panel>
      <Panel className="span-12" title="Delivery Queue">
        <SimpleTable rows={deliveries} columns={['deliveryNo', 'saleNo', 'customerName', 'products', 'destination', 'driver', 'vehicle', 'status']} />
      </Panel>
      {detailOrder && (
        <div className="modal-backdrop" onClick={() => setDetailOrder(null)}>
          <div className="modal-card wide" onClick={e => e.stopPropagation()}>
            <header><h2>{detailOrder.saleNo || 'Sales order'}</h2><button type="button" onClick={() => setDetailOrder(null)}><X size={18} /></button></header>
            <div className="settings-kv-grid">
              <article><span>Customer</span><strong>{detailOrder.customerName || '—'}</strong></article>
              <article><span>Total</span><strong>{currency(detailOrder.total)}</strong></article>
              <article><span>Paid</span><strong>{currency(detailOrder.paid)}</strong></article>
              <article><span>Balance</span><strong>{currency(detailOrder.balance || (num(detailOrder.total) - num(detailOrder.paid)))}</strong></article>
              <article><span>Delivery</span><strong>{detailOrder.liveStatus || detailOrder.deliveryStatus || '—'}</strong></article>
              <article><span>Delivery no.</span><strong>{detailOrder.deliveryNo || '—'}</strong></article>
              <article><span>Date</span><strong>{String(detailOrder.date || detailOrder.createdAt || '').slice(0, 10) || '—'}</strong></article>
              <article><span>Payment</span><strong>{detailOrder.paymentMethod || '—'}</strong></article>
              <article><span>Destination</span><strong>{detailOrder.destination || '—'}</strong></article>
              <article><span>Products</span><strong>{detailOrder.productCount != null ? `${detailOrder.productCount} product${detailOrder.productCount === 1 ? '' : 's'} · ${detailOrder.totalQty || 0} units` : (detailOrder.items && detailOrder.items.length ? `${detailOrder.items.length} line(s)` : '—')}</strong></article>
              <article><span>Product list</span><strong title={detailOrder.productsSummary}>{detailOrder.productsSummary || '—'}</strong></article>
            </div>
            <div className="invoice-actions-row" style={{ marginTop: 12, display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              {canGenerateInvoice && <button className="primary-action" type="button" onClick={() => generateInvoice(detailOrder)}><ReceiptText size={14} /> Invoice</button>}
              <button className="secondary-action" type="button" onClick={() => copyText(rowSummary(detailOrder))}><FileText size={14} /> Copy</button>
              <button className="secondary-action" type="button" onClick={() => printText(detailOrder.saleNo || 'Order', rowSummary(detailOrder))}><Printer size={14} /> Print</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function NewSaleModal({ user, onClose, onSaved }) {
  const lookup = useServer(user, 'getLookupData');
  const [form, setForm] = useState({ customerId: '', customerName: '', customerEmail: '', customerPhone: '', productId: '', quantity: 1, paid: 0, paymentMethod: 'Credit', taxStatus: 'Taxable', destination: '', deliveryMethod: 'Company Vehicle', driver: '', vehicle: '', notes: '' });
  const [saving, setSaving] = useState(false);
  if (lookup.loading) return <div className="modal-backdrop"><div className="modal-card"><Loader2 className="spin" /> Loading sale form...</div></div>;
  if (lookup.error) return <div className="modal-backdrop"><div className="modal-card">Unable to load sale form: {lookup.error}</div></div>;
  const products = lookup.data.products || [];
  const customers = lookup.data.customers || [];
  const selectedProduct = products.find(p => p.id === form.productId) || products[0] || {};
  const selectedQty = num(form.quantity || 1);
  const selectedPrice = num(selectedProduct.price || 0);
  const selectedCost = num(selectedProduct.cost || 0);
  const selectedStock = num(selectedProduct.stock || 0);
  const lookupVat = lookup.data.taxSettings || { vatRate: 16, vatEnabled: true, vatInclusive: false };
  const projectedSubtotal = Math.round(selectedQty * selectedPrice);
  const vatEnabledConfigured = lookupVat.vatEnabled !== false && lookupVat.active !== false;
  const projectedVat = vatEnabledConfigured && !(form.taxStatus === 'Exempt' || form.taxStatus === 'Zero Rated')
    ? (lookupVat.vatInclusive === true
      ? Math.round(projectedSubtotal - projectedSubtotal / (1 + num(lookupVat.vatRate) / 100))
      : Math.round(projectedSubtotal * (num(lookupVat.vatRate) / 100)))
    : 0;
  const projectedTotal = projectedSubtotal + projectedVat;
  const stockWarning = selectedProduct.id && selectedStock < selectedQty;
  const lowStockWarning = selectedProduct.id && !stockWarning && selectedStock - selectedQty <= num(selectedProduct.minStock || 0);
  async function saveOrder(e) {
    e.preventDefault();
    setSaving(true);
    try {
      const matched = customers.find(c => c.id === form.customerId || String(c.name || '').toLowerCase() === String(form.customerName || '').trim().toLowerCase());
      await rpc('createSalesOrder', [user, { ...form, customerId: matched?.id || form.customerId, customerName: form.customerName || matched?.name, productId: form.productId || selectedProduct.id, unitPrice: selectedProduct.price }]);
      onSaved?.();
    } catch (error) {
      alert(error.message || 'Could not create sales order');
    } finally {
      setSaving(false);
    }
  }
  return (
    <div className="modal-backdrop">
      <form className="modal-card" onSubmit={saveOrder}>
        <header><h2>New Sales Order</h2><button type="button" onClick={onClose}><X size={18} /></button></header>
        <label>Customer / Company Name<input list="sales-customers" value={form.customerName} onChange={e => {
          const match = customers.find(c => String(c.name || '').toLowerCase() === e.target.value.trim().toLowerCase());
          setForm({ ...form, customerName: e.target.value, customerId: match?.id || '', customerEmail: match?.email || form.customerEmail, customerPhone: match?.phone || form.customerPhone, destination: match?.city || form.destination });
        }} placeholder="Type company or customer name" required /></label>
        <datalist id="sales-customers">{customers.map(c => <option key={c.id} value={c.name}>{c.phone || c.email || ''}</option>)}</datalist>
        <div className="modal-grid">
          <label>Customer Email<input type="email" value={form.customerEmail} onChange={e => setForm({ ...form, customerEmail: e.target.value })} placeholder="Optional for invoice email" /></label>
          <label>Customer Phone<input value={form.customerPhone} onChange={e => setForm({ ...form, customerPhone: e.target.value })} placeholder="Optional" /></label>
        </div>
        <label>Product<select value={form.productId} onChange={e => setForm({ ...form, productId: e.target.value })} required><option value="">Select product</option>{products.map(p => <option key={p.id} value={p.id}>{p.name} - {currency(p.price)} - stock {num(p.stock).toLocaleString()}</option>)}</select></label>
        {selectedProduct.id && (
          <div className={`sales-order-pricing ${stockWarning ? 'danger' : lowStockWarning ? 'warn' : ''}`}>
            <article><span>Unit Price</span><strong>{currency(selectedPrice)}</strong></article>
            <article><span>Available Stock</span><strong>{selectedStock.toLocaleString()} {selectedProduct.unit || ''}</strong></article>
            <article><span>Line Amount</span><strong>{currency(projectedSubtotal)}</strong></article>
            <article><span>VAT ({num(lookupVat.vatRate)}%)</span><strong>{currency(projectedVat)}</strong></article>
            <article><span>Order Total (incl. VAT)</span><strong>{currency(projectedTotal)}</strong></article>
            {stockWarning && <p>Insufficient stock. Reduce quantity or restock before confirming.</p>}
            {lowStockWarning && <p>This order will push stock close to reorder level.</p>}
          </div>
        )}
        <div className="modal-grid">
          <label>Quantity<input type="number" min="1" value={form.quantity} onChange={e => setForm({ ...form, quantity: e.target.value })} /></label>
          <label>Paid<input type="number" min="0" value={form.paid} onChange={e => setForm({ ...form, paid: e.target.value })} /></label>
        </div>
        <div className="modal-grid">
          <label>VAT / Tax Status<select value={form.taxStatus} onChange={e => setForm({ ...form, taxStatus: e.target.value })}>
            {['Taxable', 'Exempt', 'Zero Rated'].map(x => <option key={x} value={x}>{x === 'Taxable' ? `${x} (${num(lookupVat.vatRate)}% ${lookupVat.taxName || 'VAT'})` : x}</option>)}
          </select></label>
          <label>Payment Method<select value={form.paymentMethod} onChange={e => setForm({ ...form, paymentMethod: e.target.value })}>
            {['Cash', 'Bank Transfer', 'M-Pesa', 'Cheque', 'Direct Transfer', 'Credit', 'Mobile Money', 'Mixed Payments'].map(x => <option key={x}>{x}</option>)}
          </select></label>
        </div>
        <div className="modal-grid">
          <label>Driver<input value={form.driver} onChange={e => setForm({ ...form, driver: e.target.value })} placeholder="Optional" /></label>
          <label>Vehicle<input value={form.vehicle} onChange={e => setForm({ ...form, vehicle: e.target.value })} placeholder="Optional" /></label>
        </div>
        <div className="modal-grid">
          <label>Delivery Destination<input value={form.destination} onChange={e => setForm({ ...form, destination: e.target.value })} placeholder="Customer location / branch" /></label>
          <label>Delivery Method<select value={form.deliveryMethod} onChange={e => setForm({ ...form, deliveryMethod: e.target.value })}>{['Company Vehicle', 'Courier', 'Pickup', 'Motorbike', 'Third-party Transport'].map(x => <option key={x}>{x}</option>)}</select></label>
        </div>
        <label>Delivery Notes<input value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Special handling, contact person, receiving notes..." /></label>
        <button className="primary-action" disabled={saving || stockWarning}>{saving ? 'Creating...' : stockWarning ? 'Insufficient Stock' : 'Create Order + Delivery'}</button>
      </form>
    </div>
  );
}

