function SalesAi({ insights, overview = {}, team = [] }) {
  const clean = (t) => String(t || '')
    .replace(/[\u{1F000}-\u{1FAFF}]/gu, '')
    .replace(/[\u{2600}-\u{27BF}]/gu, '')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/^\s*([-_*~])\1{2,}\s*$/gm, '')
    .trim();
  const opsRows = [
    { focus: 'Revenue', value: currency(overview.revenue), note: 'Period revenue from confirmed orders' },
    { focus: 'Pipeline', value: currency(overview.pipeline), note: 'Open quotes and opportunities' },
    { focus: 'Unpaid invoices', value: overview.unpaidInvoices || 0, note: 'Needs collection follow-up' },
    { focus: 'Pending delivery', value: overview.pendingDelivery || 0, note: 'Orders still in dispatch queue' },
    { focus: 'Quote conversion', value: `${overview.quoteConversion || 0}%`, note: 'Quotes converted to orders' },
    { focus: 'Repeat customers', value: overview.repeatCustomers || 0, note: 'Customers with more than one order' }
  ];
  const ranked = [...(team || [])].sort((a, b) => num(b.revenue || 0) - num(a.revenue || 0)).slice(0, 6);
  const notes = (insights || []).map(item => ({
    title: clean(item.title || item.label || 'Sales note'),
    detail: clean(item.detail || item.message || item.summary || '')
  })).filter(x => x.title && x.detail).slice(0, 8);
  return (
    <div className="dashboard-grid">
      <Panel className="span-6" title="Sales operating snapshot" action="From live workspace">
        <SimpleTable rows={opsRows} columns={['focus', 'value', 'note']} />
      </Panel>
      <Panel className="span-6" title="Team ranking" action="By revenue">
        <SimpleTable
          rows={ranked.map(r => ({
            rep: r.name || r.salesRep || r.rep || '—',
            revenue: currency(r.revenue),
            orders: r.orders || r.orderCount || '—',
            customers: r.customers || r.customerCount || '—'
          }))}
          columns={['rep', 'revenue', 'orders', 'customers']}
        />
      </Panel>
      <Panel className="span-12" title="Sales notes" action={`${notes.length} items`}>
        <div className="metric-stack">
          {notes.length === 0 && <div className="empty-state">No sales notes yet. Pipeline, unpaid invoices, and territory gaps will appear here as activity grows.</div>}
          {notes.map((item, i) => (
            <div key={`${item.title}-${i}`}>
              <span>{item.title}</span>
              <strong style={{ fontWeight: 500, maxWidth: '70%', textAlign: 'right' }}>{item.detail}</strong>
            </div>
          ))}
        </div>
      </Panel>
    </div>
  );
}

